//! Writes the generated files transports and the TS SDK consume (layout: the crate docs).

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::Path;
use std::{fs, io};

use schemars::generate::SchemaSettings;
use serde_json::json;
use ts_rs::TS;

use crate::{MethodInfo, Out, METHODS, PROTOCOL_VERSION};

/// 64-bit counters (`seq`, `tick`, `version`) stay JSON numbers; ids opt out with `#[ts(type = "string")]`.
pub fn ts_config(out_dir: &Path) -> ts_rs::Config {
    ts_rs::Config::new().with_large_int("number").with_out_dir(out_dir)
}

/// Writes `methods.json`, `methods.ts` and `types/*.ts` under `dir`.
pub fn generate(dir: &Path) -> io::Result<()> {
    let cfg = ts_config(&dir.join("types"));
    let ts = |r: Result<(), ts_rs::ExportError>| r.map_err(io::Error::other);
    ts(Out::export_all(&cfg))?;
    for m in METHODS {
        ts((m.params.ts_export)(&cfg))?;
        ts((m.result.ts_export)(&cfg))?;
    }
    fs::write(dir.join("methods.ts"), methods_ts(&cfg))?;
    fs::write(dir.join("methods.json"), methods_json())
}

/// Each method's description, lane, flags and standalone param and result schemas (JSON Schema 2020-12), for
/// MCP tool lists and runtime validation.
pub fn methods_json() -> String {
    let methods: Vec<_> = METHODS
        .iter()
        .map(|m| {
            json!({
                "name": m.name,
                "description": doc_lines(m).join("\n"),
                "lane": m.lane,
                "flags": m.flags,
                "params": (m.params.schema)(SchemaSettings::draft2020_12().for_deserialize()),
                "result": (m.result.schema)(SchemaSettings::draft2020_12().for_serialize()),
            })
        })
        .collect();
    let doc = json!({ "protocolVersion": PROTOCOL_VERSION, "methods": methods });
    serde_json::to_string_pretty(&doc).expect("schemas serialize") + "\n"
}

/// The `Methods` map (name → params, result, lane) in the style of CDP's `protocol-mapping.d.ts`.
pub fn methods_ts(cfg: &ts_rs::Config) -> String {
    let mut imports = BTreeSet::new();
    for info in METHODS.iter().flat_map(|m| [&m.params, &m.result]) {
        if let Some(path) = (info.ts_path)() {
            let module = path.with_extension("");
            imports.insert(format!("import type {{ {} }} from \"./types/{}\";", (info.ts_name)(cfg), module.display()));
        }
    }
    let mut ts = String::from("// Generated by acacia-api from src/methods.rs; do not edit (regenerate: tests/generated.rs).\n");
    for line in &imports {
        ts += line;
        ts.push('\n');
    }
    let _ = write!(ts, "\nexport const PROTOCOL_VERSION = {PROTOCOL_VERSION};\n\n");
    ts += "export type Lane = \"host\" | \"queued\" | \"immediate\";\n\nexport interface Methods {\n";
    for m in METHODS {
        ts += "  /**\n";
        for line in doc_lines(m) {
            let _ = writeln!(ts, "   * {line}");
        }
        for flag in m.flags {
            let _ = writeln!(ts, "   * @{flag}");
        }
        let lane = serde_json::to_string(&m.lane).expect("lane serializes");
        let (params, result) = ((m.params.ts_name)(cfg), (m.result.ts_name)(cfg));
        let _ = writeln!(ts, "   */\n  \"{}\": {{ params: {params}; result: {result}; lane: {lane} }};", m.name);
    }
    ts += "}\n\nexport type MethodName = keyof Methods;\n";
    ts += "export type Params<M extends MethodName> = Methods[M][\"params\"];\n";
    ts += "export type Result<M extends MethodName> = Methods[M][\"result\"];\n";
    ts += "/** One call as a transport sends it. */\n";
    ts += "export type Command = { [M in MethodName]: { call: number; method: M; params: Params<M> } }[MethodName];\n";
    ts
}

fn doc_lines(m: &MethodInfo) -> Vec<&'static str> {
    m.doc.lines().map(|l| l.strip_prefix(' ').unwrap_or(l)).collect()
}
